#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_maskFrom;
uniform float amzp_style;
uniform float amzp_amp;
uniform float amzp_freq;
uniform float amzp_phase;
uniform float amzp_zDist;
uniform float amzp_mbOn;
uniform float amzp_mbLen;
uniform float amzp_seed;
uniform float amzp_wrapX;
uniform float amzp_wrapY;
uniform float amzp_xRA;
uniform float amzp_xRF;
uniform float amzp_xWA;
uniform float amzp_xWF;
uniform float amzp_xPh;
uniform float amzp_yRA;
uniform float amzp_yRF;
uniform float amzp_yWA;
uniform float amzp_yWF;
uniform float amzp_yPh;
uniform float amzp_zRA;
uniform float amzp_zRF;
uniform float amzp_zWA;
uniform float amzp_zWF;
uniform float amzp_zPh;
uniform float amzp_tRA;
uniform float amzp_tRF;
uniform float amzp_tWA;
uniform float amzp_tWF;
uniform float amzp_tPh;
uniform float amzp_rAmp;
uniform float amzp_gAmp;
uniform float amzp_bAmp;
uniform float amzp_rPh;
uniform float amzp_gPh;
uniform float amzp_bPh;
uniform float amzp_rgbRand;
uniform float amzp_rgbFreq;
uniform float amzp_opMode;
uniform float amzp_maskUse;
uniform float amzp_maskBlur;
uniform float amzp_maskInv;
uniform float amzp_cropL;
uniform float amzp_cropR;
uniform float amzp_cropT;
uniform float amzp_cropB;
uniform float amzp_quality;
uniform float amzp_fps;
    float PX;
    float2 W;
    float2 CC;
    float qMul() { return amzp_quality < 1.5 ? 0.25 : (amzp_quality < 2.5 ? 0.5 : (amzp_quality < 3.5 ? 1.0 : (amzp_quality < 4.5 ? 1.5 : 2.0))); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float hh(float x, float k) { return fract(sin(x * 91.345 + k * 47.13 + amzp_seed * 13.7) * 43758.5453); }
    float vn1(float x, float k) { float i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(hh(i, k), hh(i + 1.0, k), f) * 2.0 - 1.0; }
    float rnd(float x, float k) {
        if (int(amzp_style) == 2) return hh(floor(x), k) * 2.0 - 1.0;
        float v = vn1(x, k);
        if (int(amzp_style) == 1) {
            v = 0.65 * v + 0.35 * vn1(x * 2.9 + 1.7, k + 11.0);
            v = sign(v) * pow(abs(v), 0.6);
        }
        return v;
    }
    float axis(float t, float k, float ra, float rf, float wa, float wf, float ph) {
        float F = max(amzp_freq, 0.0);
        float g = ph + amzp_phase;
        float r = ra != 0.0 ? ra * rnd(t * F * rf + g, k) : 0.0;
        float w = wa != 0.0 ? wa * sin(6.2831853 * (t * F * wf + g)) : 0.0;
        return r + w;
    }
    float4 shk(float t) {
        return float4(
            axis(t, 1.0, amzp_xRA, amzp_xRF, amzp_xWA, amzp_xWF, amzp_xPh),
            axis(t, 2.0, amzp_yRA, amzp_yRF, amzp_yWA, amzp_yWF, amzp_yPh),
            axis(t, 3.0, amzp_zRA, amzp_zRF, amzp_zWA, amzp_zWF, amzp_zPh),
            axis(t, 4.0, amzp_tRA, amzp_tRF, amzp_tWA, amzp_tWF, amzp_tPh)) * amzp_amp;
    }
    float wrap1(float u, int m) {
        if (m == 0) return 1.0 - abs(1.0 - mod(u, 2.0));
        if (m == 1) return fract(u);
        return clamp(u, 0.0, 1.0);
    }
    float4 sampleP(float2 p, float4 cr) {
        float2 sz = max(cr.zw - cr.xy, float2(1.0));
        float2 u = (p - cr.xy) / sz;
        if ((int(amzp_wrapX) == 3 && (u.x < 0.0 || u.x > 1.0)) || (int(amzp_wrapY) == 3 && (u.y < 0.0 || u.y > 1.0))) return float4(0.0);
        u = float2(wrap1(u.x, int(amzp_wrapX)), wrap1(u.y, int(amzp_wrapY)));
        return amzTexture(0, l2s((cr.xy + u * sz) / W));
    }
    float4 tap(float2 p, float t, float cA, float4 cr) {
        float4 s = shk(t) * cA;
        float D = max(amzp_zDist, 0.05) * max(W.x, W.y);
        float zs = s.z * PX;
        float z = D / max(D - zs, 0.05 * D);
        float r = radians(s.w);
        float2 q = p - CC - float2(s.x, s.y) * PX;
        float cs = cos(-r), sn = sin(-r);
        q = float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y) / z;
        return sampleP(CC + q, cr);
    }
    float maskAt(float2 p) {
        float rad = amzp_maskBlur * PX;
        float4 c = amzTexture(0, l2s(p / W));
        float m = int(amzp_maskUse) == 1 ? c.a : dot(c.rgb, float3(0.299, 0.587, 0.114));
        if (rad > 0.5) {
            float sum = m, wsum = 1.0;
            for (int i = 0; i < 8; i++) {
                float a = float(i) * 2.399963 ;
                float d = sqrt((float(i) + 0.5) / 8.0) * rad;
                float4 s = amzTexture(0, l2s((p + float2(cos(a), sin(a)) * d) / W));
                sum += int(amzp_maskUse) == 1 ? s.a : dot(s.rgb, float3(0.299, 0.587, 0.114));
                wsum += 1.0;
            }
            m = sum / wsum;
        }
        m = clamp(m, 0.0, 1.0);
        return (amzp_maskInv>0.5) ? 1.0 - m : m;
    }
    void amzRender() {
        W = layer;
        float2 p = amzLayerNorm() * W;
        CC = W * 0.5;
        PX = screen.zw.x / max(screen.zw.x, 1.0);
        float4 cr = float4(amzp_cropL * PX, amzp_cropB * PX, W.x - amzp_cropR * PX, W.y - amzp_cropT * PX);
        bool split = abs(amzp_rAmp - amzp_gAmp) > 0.0001 || abs(amzp_gAmp - amzp_bAmp) > 0.0001 || amzp_rPh != 0.0 || amzp_gPh != 0.0 || amzp_bPh != 0.0 || amzp_rgbRand > 0.0;
        float F1 = 1.0 / max(amzp_freq, 0.01);
        float mbT = (amzp_mbOn>0.5) ? max(amzp_mbLen, 0.0) / max(amzp_fps, 1.0) : 0.0;
        float n = mbT > 0.00001 ? max(2.0, floor(8.0 * qMul() + 0.5)) : 1.0;
        float4 acc = float4(0.0);
        for (int i = 0; i < 16; i++) {
            float fi = float(i);
            if (fi >= n) break;
            float ts = time + (n > 1.0 ? (fi / (n - 1.0) - 0.5) * mbT : 0.0);
            if (split) {
                float rr = amzp_rgbRand * 0.5 * F1;
                float4 cR = tap(p, ts + amzp_rPh * F1 + rr * vn1(ts * amzp_rgbFreq, 21.0), amzp_rAmp, cr);
                float4 cG = tap(p, ts + amzp_gPh * F1 + rr * vn1(ts * amzp_rgbFreq, 22.0), amzp_gAmp, cr);
                float4 cB = tap(p, ts + amzp_bPh * F1 + rr * vn1(ts * amzp_rgbFreq, 23.0), amzp_bAmp, cr);
                acc += float4(cR.r, cG.g, cB.b, max(cR.a, max(cG.a, cB.a)));
            } else {
                acc += tap(p, ts, amzp_gAmp, cr);
            }
        }
        float4 o = acc / n;
        o = float4(min(o.rgb, float3(o.a)), o.a);
        float4 src = amzTexture(0, l2s(amzLayerNorm()));
        if (int(amzp_opMode) == 1) o *= src.a;
        else if (int(amzp_opMode) == 2) o = o + src * (1.0 - o.a);
        if (int(amzp_maskFrom) == 1) o = mix(src, o, maskAt(p));
        amzOutput = o;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
